create extension if not exists "pgcrypto";
create table if not exists categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,icon text,display_order integer default 0,is_active boolean default true,created_at timestamptz default now());
create table if not exists brands(id uuid primary key default gen_random_uuid(),name text not null,logo_url text,description text,display_order integer default 0,is_active boolean default true,created_at timestamptz default now());
create table if not exists products(id uuid primary key default gen_random_uuid(),category_id uuid references categories(id) on delete set null,brand_id uuid references brands(id) on delete set null,name text not null,slug text unique not null,unit text,price numeric,price_note text,stock_status text default 'Còn hàng',description text,thumbnail text,is_featured boolean default false,badge text,display_order integer default 0,is_active boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists product_images(id uuid primary key default gen_random_uuid(),product_id uuid references products(id) on delete cascade,image_url text not null,display_order integer default 0);
create table if not exists price_history(id uuid primary key default gen_random_uuid(),product_id uuid references products(id) on delete cascade,price numeric,price_note text,created_at timestamptz default now());
create table if not exists projects(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,thumbnail text,location text,project_type text,description text,materials text[],status text,completed_date date,display_order integer default 0,is_active boolean default true,created_at timestamptz default now());
create table if not exists reviews(id uuid primary key default gen_random_uuid(),name text not null,avatar text,company text,position text,rating integer check(rating between 1 and 5),content text not null,display_order integer default 0,is_featured boolean default false,created_at timestamptz default now());
create table if not exists news(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,thumbnail text,summary text,content text,category text,published_at timestamptz,reading_time integer,is_featured boolean default false,display_order integer default 0,status text default 'draft',created_at timestamptz default now());
create table if not exists quotation_requests(id uuid primary key default gen_random_uuid(),full_name text not null,phone text not null,delivery_address text,materials text[],estimated_quantity text,note text,status text default 'Mới tiếp nhận',created_at timestamptz default now());
create table if not exists advantages(id uuid primary key default gen_random_uuid(),title text not null,description text,icon text,display_order integer default 0,is_active boolean default true);
create table if not exists company_statistics(id uuid primary key default gen_random_uuid(),title text not null,value text not null,icon text,display_order integer default 0,is_active boolean default true);
create table if not exists company_information(id uuid primary key default gen_random_uuid(),company_name text,address text,hotline text,email text,working_hours text,google_map_embed text,zalo_link text,facebook_link text,youtube_link text,updated_at timestamptz default now());
alter table quotation_requests enable row level security;
create policy "Anyone can create quotation requests" on quotation_requests for insert to anon,authenticated with check(true);
